package com.nextaicommerce.platform.shipping;
import java.util.*;import java.math.BigDecimal;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;import tools.jackson.databind.ObjectMapper;import org.apache.pdfbox.Loader;import org.apache.pdfbox.text.PDFTextStripper;
class PackingDisplayFallbackTest {
 @Test void mappedDisplayFallbackPreservesExactIdsQuantitiesAndFrozenJson()throws Exception{
  var item=UUID.randomUUID();var location=UUID.randomUUID();var row=CarrierLabelComposer.Line.accountItem("Brand",null,"Product",new BigDecimal("12.0000"),"",item,location).withPackage("FedEx Pak");
  assertThat(row.sku()).isEqualTo("N/A");assertThat(row.allocations().getFirst().location()).isEqualTo("N/A");assertThat(row.mappedQuantity()).isEqualByComparingTo("12");var json=new ObjectMapper();var frozen=json.readValue(json.writeValueAsString(row),CarrierLabelComposer.Line.class);assertThat(frozen).isEqualTo(row);assertThat(frozen.accountItemId()).isEqualTo(item);assertThat(frozen.locationId()).isEqualTo(location);new CarrierLabelComposer().validateCompact(List.of(frozen));
 }
 @Test void equalFallbackTextNeverEquatesDifferentMappedItemsOrLocations(){var item=UUID.randomUUID();var location=UUID.randomUUID();var row=CarrierLabelComposer.Line.accountItem("Brand",null,"Product",new BigDecimal("12"),null,item,location);var frozen=row.withPackage("Pak");assertThat(LocalFedExShippingUat.samePacking(List.of(row),List.of(frozen))).isTrue();assertThat(LocalFedExShippingUat.samePacking(List.of(CarrierLabelComposer.Line.accountItem("Brand",null,"Product",new BigDecimal("12.0000"),null,item,location)),List.of(frozen))).isTrue();for(var other:List.of(CarrierLabelComposer.Line.accountItem("Brand",null,"Product",new BigDecimal("12"),null,UUID.randomUUID(),location),CarrierLabelComposer.Line.accountItem("Brand",null,"Product",new BigDecimal("12"),null,item,UUID.randomUUID()),CarrierLabelComposer.Line.accountItem("Brand",null,"Product",new BigDecimal("11"),null,item,location)))assertThat(LocalFedExShippingUat.samePacking(List.of(other),List.of(frozen))).isFalse();}
 @Test void displayFallbackDoesNotReplaceMissingInventoryEvidence(){assertThatThrownBy(()->CarrierLabelComposer.Line.accountItem("Brand",null,"Product",BigDecimal.ONE,null,null,UUID.randomUUID())).hasMessageContaining("identities");assertThatThrownBy(()->CarrierLabelComposer.Line.accountItem("Brand",null,"Product",BigDecimal.ZERO,null,UUID.randomUUID(),UUID.randomUUID())).hasMessageContaining("positive");}
 @Test void existingCodesRemainExact(){var row=CarrierLabelComposer.Line.accountItem("Brand","000001","Product",BigDecimal.ONE,"F7",UUID.randomUUID(),UUID.randomUUID());assertThat(row.sku()).isEqualTo("000001");assertThat(row.allocations().getFirst().location()).isEqualTo("F7");}
}
